select e.event_code,e.sport_name,count(m.id) total_matches,count(m.id) filter(where not m.takraw_reviewed) review_pending from public.sports_events e join public.sports_competitions c on c.id=e.competition_id left join public.sports_football_matches m on m.event_id=e.id where c.slug='phayao-secondary-group-sports-2569' and e.event_code like 'GS3-ST-%' group by e.id,e.event_code,e.sport_name order by e.event_code;
